import cc.iili.tools.crossmool.tool.SM4Util;
import cc.iili.tools.crossmool.util.HexUtil;

public class PythonGcmDecryptTest {
    public static void main(String[] args) throws Exception {
        byte[] key = HexUtil.decodeHexStr("ad1486d58d4e012d4c94936616ecf7d6");
        
        // Python GCM ciphertext (generated by Python sm4_util.encrypt_gcm_string)
        String pythonCt = args[0];
        
        try {
            String pt = SM4Util.decryptGcmNativeToString(key, pythonCt);
            System.out.println("Java decrypt Python GCM: " + pt);
            if (pt.equals("Hello, 這是国密SM4測試數據")) {
                System.out.println("[PASS] Python encrypt -> Java(Native) decrypt");
            } else {
                System.out.println("[FAIL] Mismatch: got '" + pt + "'");
            }
        } catch (Exception e) {
            System.out.println("[FAIL] Java Native decrypt error: " + e.getMessage());
        }
        
        try {
            String pt2 = SM4Util.decryptGcmJca(key, pythonCt);
            System.out.println("Java JCA decrypt Python GCM: " + pt2);
            if (pt2.equals("Hello, 這是国密SM4測試數據")) {
                System.out.println("[PASS] Python encrypt -> Java(JCA) decrypt");
            } else {
                System.out.println("[FAIL] Mismatch: got '" + pt2 + "'");
            }
        } catch (Exception e) {
            System.out.println("[FAIL] Java JCA decrypt error: " + e.getMessage());
        }
    }
}
